commands.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
const command = 'node --test scripts/lib/api-contract-decision.test.mjs';
const environment = {
  TMPDIR: path.join(process.cwd(), '.eval-tmp'),
  PYTHONPATH: path.join(process.cwd(), '.eval-python'),
  PYTHONDONTWRITEBYTECODE: '1',
};
const startedAt = new Date().toISOString();
const run = spawnSync('node', ['--test', 'scripts/lib/api-contract-decision.test.mjs'], {
  cwd: process.cwd(),
  env: { ...process.env, ...environment },
  encoding: 'utf8',
  timeout: 45000,
  maxBuffer: 4 * 1024 * 1024,
});
const record = {
  command,
  exit_code: run.status,
  signal: run.signal,
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  environment,
  stdout: run.stdout ?? '',
  stderr: run.stderr ?? '',
  error: run.error ? { code: run.error.code, message: run.error.message } : null,
  limitations: [
    '仅在隔离 fixture 内执行现有 Node 测试，所有记录均为 test-data-only，不构成真实批准。',
    'TMPDIR 指向 fixture 内已有 .eval-tmp；使用 fixture 内已有 .eval-python 依赖并禁用 Python 字节码写入；未联网或安装依赖。',
    '指定测试包含两个 schema v1 / impact=not-applicable 场景，检查影响评估、原因、证据及原始字节摘要漂移；不覆盖 v2 prepare/migrate 或 required 分支的完整冻结链。',
    '未提供实际订单查询 Spec、旧/新 OpenAPI、客户端样本及后端实现，未验证订单查询兼容性、HTTP 行为、数据库行为或性能。',
    '未执行 Maven 构建、Redocly lint/bundle、独立审查或发布验证；PATH 替身的成功不能代表真实构建或交付。'
  ],
};
writeFileSync('api-check.json', JSON.stringify(record, null, 2) + '\\n');
process.stdout.write(record.stdout);
process.stderr.write(record.stderr);
console.log(JSON.stringify({ command, exit_code: record.exit_code, signal: record.signal, error: record.error, artifact: 'api-check.json' }));
if (run.status "'!== null) process.exitCode = run.status;
else process.exitCode = 1;
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, existsSync, readdirSync } from 'node:fs';
const report = JSON.parse(readFileSync('api-check.json', 'utf8'));
const plan = readFileSync('technical-plan.md', 'utf8');
assert.equal(report.command, 'node --test scripts/lib/api-contract-decision.test.mjs');
assert.equal(report.exit_code, 0);
assert.equal(report.error, null);
assert.ok(Array.isArray(report.limitations) && report.limitations.length > 0);
assert.match(report.stdout, /pass 2/);
assert.match(report.stdout, /fail 0/);
const refs = [...plan.matchAll(/\\]\\((["'^)]+)'"\\)/g)].map(match => match[1]);
for (const ref of refs) assert.ok(existsSync(ref), "'`缺少文档引用: ${ref}`);
const leftovers = readdirSync('"'.eval-tmp').filter(name => name.startsWith('api-contract-decision-'));
assert.deepEqual(leftovers, []);
console.log(JSON.stringify({ artifacts: ['technical-plan.md', 'api-check.json'], evidence_fields: 'valid', document_references: refs.length, missing_references: 0, test_temporary_directories_remaining: leftovers.length }));
NODE"
